fn solve(s: &Vec<char>) -> Vec<char> {
    // Pre-allocate enough space for the original word plus up to two extra characters
    let mut result = Vec::with_capacity(s.len() + 2);
    
    // Copy the original characters
    result.extend(s.iter());
    
    // Check the last character (safe because input is non-empty)
    if let Some(&last_char) = s.last() {
        if last_char == 's' {
            // If the word ends with 's', append "es"
            result.push('e');
            result.push('s');
        } else {
            // Otherwise, just append "s"
            result.push('s');
        }
    }
    
    result
}

